<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Developer Portfolio - Mobile Hero</title>
    <style>
        :root {
            --bg-color: #0a0a0b;
            --text-primary: #ffffff;
            --text-secondary: #9ca3af;
            --accent-gradient: linear-gradient(135deg, #3b82f6, #8b5cf6, #ec4899);
            --pill-bg: rgba(255, 255, 255, 0.05);
            --pill-border: rgba(255, 255, 255, 0.1);
            --btn-primary-bg: #ffffff;
            --btn-primary-text: #000000;
            --btn-secondary-bg: rgba(255, 255, 255, 0.08);
            --btn-secondary-border: rgba(255, 255, 255, 0.15);
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-primary);
            font-family: var(--font-sans);
            /* Simulating the mobile viewport constraint */
            max-width: 390px; 
            margin: 0 auto;
            min-height: 100vh;
            position: relative;
            overflow-x: hidden;
        }

        /* --- Header --- */
        header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 20px 24px;
        }

        .brand {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .avatar {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: linear-gradient(135deg, #3b82f6, #d946ef);
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 700;
            font-size: 18px;
            color: white;
        }

        .name {
            font-weight: 700;
            font-size: 16px;
            letter-spacing: -0.02em;
        }

        .menu-icon {
            width: 24px;
            height: 20px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            cursor: pointer;
        }

        .menu-line {
            width: 100%;
            height: 2px;
            background-color: white;
            border-radius: 2px;
        }

        /* --- Main Content --- */
        main {
            padding: 40px 24px 60px 24px;
            display: flex;
            flex-direction: column;
            gap: 32px;
        }

        /* Availability Pill */
        .status-pill {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            background-color: var(--pill-bg);
            border: 1px solid var(--pill-border);
            padding: 10px 16px;
            border-radius: 999px;
            width: fit-content;
            backdrop-filter: blur(4px);
        }

        .status-dot {
            width: 8px;
            height: 8px;
            background-color: #10b981;
            border-radius: 50%;
            box-shadow: 0 0 8px rgba(16, 185, 129, 0.5);
        }

        .status-text {
            font-size: 13px;
            color: var(--text-secondary);
            font-weight: 500;
            letter-spacing: 0.01em;
        }

        /* Typography */
        .hero-text-group {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .greeting {
            font-size: 14px;
            text-transform: uppercase;
            letter-spacing: 0.1em;
            color: var(--text-secondary);
            font-weight: 600;
        }

        h1 {
            font-size: 36px; /* Large but readable on mobile */
            line-height: 1.1;
            font-weight: 800;
            letter-spacing: -0.03em;
        }

        .gradient-text {
            background: var(--accent-gradient);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .description {
            font-size: 16px;
            line-height: 1.6;
            color: var(--text-secondary);
            max-width: 100%; /* Prevent overflow */
        }

        /* CTAs */
        .cta-group {
            display: flex;
            flex-direction: column;
            gap: 16px;
            margin-top: 8px;
        }

        .btn {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 10px;
            height: 56px; /* >44px touch target */
            border-radius: 16px;
            font-size: 15px;
            font-weight: 700;
            cursor: pointer;
            transition: transform 0.2s ease, opacity 0.2s ease;
            text-decoration: none;
            width: 100%;
            border: none;
        }

        .btn:active {
            transform: scale(0.98);
        }

        .btn-primary {
            background-color: var(--btn-primary-bg);
            color: var(--btn-primary-text);
        }

        .btn-secondary {
            background-color: var(--btn-secondary-bg);
            color: var(--text-primary);
            border: 1px solid var(--btn-secondary-border);
        }

        /* Stats Grid */
        .stats-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 16px;
            border-top: 1px solid rgba(255,255,255,0.08);
            padding-top: 32px;
            margin-top: auto;
        }

        .stat-item {
            display: flex;
            flex-direction: column;
            gap: 4px;
        }

        .stat-value {
            font-size: 28px;
            font-weight: 800;
            color: white;
            letter-spacing: -0.02em;
        }

        .stat-label {
            font-size: 13px;
            color: var(--text-secondary);
            line-height: 1.3;
        }

        /* Floating Nav Icon (Bottom Left) */
        .floating-nav {
            position: absolute;
            bottom: 30px;
            left: 24px;
            width: 48px;
            height: 48px;
            border-radius: 50%;
            border: 1px solid rgba(255,255,255,0.2);
            background: rgba(20, 20, 20, 0.8);
            backdrop-filter: blur(10px);
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            font-family: serif;
            font-style: italic;
            z-index: 10;
        }

        /* Icons SVG styling */
        .icon {
            width: 20px;
            height: 20px;
            fill: currentColor;
        }

        .icon-sparkle {
            width: 18px;
            height: 18px;
        }

    </style>
</head>
<body>

    <!-- Header -->
    <header>
        <div class="brand">
            <div class="avatar">F</div>
            <span class="name">Faisal Khan</span>
        </div>
        <div class="menu-icon">
            <div class="menu-line"></div>
            <div class="menu-line"></div>
            <div class="menu-line"></div>
        </div>
    </header>

    <!-- Main Content -->
    <main>
        <!-- Availability -->
        <div class="status-pill">
            <div class="status-dot"></div>
            <span class="status-text">Open to full-time & freelance work</span>
        </div>

        <!-- Text Content -->
        <section class="hero-text-group">
            <p class="greeting">Hi, I'm Faisal Khan</p>
            <h1>
                Full-Stack<br>
                <span class="gradient-text">Engineer &</span><br>
                Mobile App<br>
                Developer
            </h1>
            <p class="description">
                I design and ship polished web & mobile products end-to-end — from React/Next.js dashboards to Flutter apps — with a soft spot for clean UX and AI-assisted features.
            </p>
        </section>

        <!-- Call To Actions -->
        <div class="cta-group">
            <button class="btn btn-primary">
                <!-- Sparkle Icon -->
                <svg class="icon icon-sparkle" viewBox="0 0 24 24">
                    <path d="M12 0L14.59 9.41L24 12L14.59 14.59L12 24L9.41 14.59L0 12L9.41 9.41L12 0Z" fill="black"/>
                </svg>
                Let's build something
            </button>
            <button class="btn btn-secondary">
                <!-- Download Icon -->
                <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                    <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path>
                    <polyline points="7 10 12 15 17 10"></polyline>
                    <line x1="12" y1="15" x2="12" y2="3"></line>
                </svg>
                View my stack
            </button>
        </div>

        <!-- Stats -->
        <div class="stats-grid">
            <div class="stat-item">
                <span class="stat-value">30+</span>
                <span class="stat-label">Projects shipped</span>
            </div>
            <div class="stat-item">
                <span class="stat-value">4+</span>
                <span class="stat-label">Years building</span>
            </div>
            <div class="stat-item">
                <span class="stat-value">20+</span>
                <span class="stat-label">Happy clients</span>
            </div>
        </div>
    </main>

    <!-- Floating Element -->
    <div class="floating-nav">N</div>

</body>
</html>
